/**
 * Tab 2 — Thống kê phân tích sự cố
 *
 * Charts:
 *  • Large Doughnut — Phân bố theo nhóm loại sự cố (11 slices)
 *  • Large Doughnut — Phân bố theo nhóm nguyên nhân (4 slices)
 *  • Horizontal Bar — byAffectedSubject (cross-analysis context)
 */
import React, { useCallback, useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { ChartEvent, ActiveElement } from 'chart.js';
import { Doughnut, Bar } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem, MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  BAR_OPTIONS_HORIZONTAL,
  buildBaseDateListUrl,
} from '../chartUtils';
import { ChartViewListPopover, ChartPopoverState } from './ChartViewListPopover';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
}

const ClickHint: React.FC = () => (
  <span
    title="Nhấn vào phần để xem danh sách"
    style={{ marginLeft: 6, fontSize: '0.7rem', color: '#94a3b8', fontWeight: 400, cursor: 'default' }}
  >
    <i className="fas fa-hand-pointer" />
  </span>
);

export const Tab2Analysis: React.FC<Props> = ({ report, filters }) => {
  const [popover, setPopover] = useState<ChartPopoverState | null>(null);
  const closePopover = useCallback(() => setPopover(null), []);

  const makeClickHandler = (
    items: ChartDataItem[],
    hintBuilder: (item: ChartDataItem) => string,
  ) => (chartEvent: ChartEvent, elements: ActiveElement[]) => {
    if (!elements.length) { setPopover(null); return; }
    const idx  = elements[0].index;
    const item = items[idx];
    if (!item || item.count === 0) { setPopover(null); return; }
    const native = chartEvent.native as MouseEvent;
    setPopover({
      x:          native.clientX,
      y:          native.clientY,
      label:      item.label,
      filterHint: hintBuilder(item),
      listUrl:    buildBaseDateListUrl(filters),
    });
  };

  const typeGroupDoughnut = {
    labels: report.byIncidentTypeGroup.map((d) => d.label),
    datasets: [
      {
        data: report.byIncidentTypeGroup.map((d) => d.count),
        backgroundColor: CHART_COLORS,
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
  };

  const causeGroupDoughnut = {
    labels: report.byCauseGroup.map((d) => d.label),
    datasets: [
      {
        data: report.byCauseGroup.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byCauseGroup.length),
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
  };

  const subjectBarData = {
    labels: report.byAffectedSubject.map((d) => d.label),
    datasets: [
      {
        label: 'Số lượng',
        data: report.byAffectedSubject.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, report.byAffectedSubject.length),
        borderRadius: 4,
      },
    ],
  };

  const doughnutOptLarge = {
    ...DOUGHNUT_OPTIONS,
    plugins: {
      ...DOUGHNUT_OPTIONS.plugins,
      legend: {
        position: 'right' as const,
        labels: {
          font: { size: 11 },
          padding: 8,
          boxWidth: 12,
        },
      },
    },
  };

  const typeGroupOptions = {
    ...doughnutOptLarge,
    onClick: makeClickHandler(
      report.byIncidentTypeGroup,
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  const causeGroupOptions = {
    ...doughnutOptLarge,
    onClick: makeClickHandler(
      report.byCauseGroup,
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  const subjectOptions = {
    ...BAR_OPTIONS_HORIZONTAL,
    onClick: makeClickHandler(
      report.byAffectedSubject,
      (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
    ),
  };

  return (
    <div>
      {popover && <ChartViewListPopover {...popover} onClose={closePopover} />}

      {/* Row 1: Two large doughnuts side by side */}
      <div className={s.grid2} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3><i className="fas fa-layer-group" /> Phân bố theo nhóm loại sự cố<ClickHint /></h3>
          <Doughnut data={typeGroupDoughnut} options={typeGroupOptions} />
        </div>
        <div className={s.chartCard}>
          <h3><i className="fas fa-sitemap" /> Phân bố theo nhóm nguyên nhân<ClickHint /></h3>
          <Doughnut data={causeGroupDoughnut} options={causeGroupOptions} />
        </div>
      </div>

      {/* Row 2: Affected subjects */}
      <div className={s.chartCard}>
        <h3><i className="fas fa-user-injured" /> Đối tượng bị ảnh hưởng<ClickHint /></h3>
        <Bar data={subjectBarData} options={subjectOptions} />
      </div>
    </div>
  );
};
