import {
  clearActiveCompanyId,
  getActiveCompanyId,
  getAuthToken,
  getAuthUser,
  isTenantSwitchAllowed,
  normCompanyCode,
  resolveInitialActiveCompanyId,
  resolveUserCompanyScope,
  setActiveCompanyId,
  setAuthUser,
} from '@linm-soft-org/linm-web-common-components';
import type { User } from '../models/User';
import { appSettings } from '../config/appSettings';
import { readJwtHomeCompanyId, readJwtTenantScope } from './jwtTenantClaims';

function hasAuthToken(): boolean {
  return Boolean(getAuthToken());
}

/** When JWT is present, sync secure-storage user blob before scope resolve (TENANT-P1-03). */
function syncUserHomeFromJwt(user: User | null | undefined): User | null | undefined {
  if (!hasAuthToken()) return user ?? getAuthUser();

  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();
  const scopedUser = user ?? getAuthUser();
  if (!jwtHome || !scopedUser) return scopedUser;

  if (scopedUser.companyId && normCompanyCode(scopedUser.companyId) === jwtHome) {
    return scopedUser;
  }

  const updated: User = {
    ...scopedUser,
    companyId: jwtHome,
    allowedCompanyIds: jwtScope.canViewAll
      ? scopedUser.allowedCompanyIds
      : jwtScope.allowedCompanyIds.length > 0
        ? jwtScope.allowedCompanyIds
        : [jwtHome],
    canViewAllCompanies: jwtScope.canViewAll,
  };
  setAuthUser(updated);
  return updated;
}

/**
 * Tenant scope for reconcile.
 * When JWT is present, use **JWT claims only** for allowlist — not `resolveUserCompanyScope`
 * Admin role override (that keeps stale LINM for platform admins).
 */
function resolveTenantScope(user: User | null | undefined): {
  homeCode: string | undefined;
  allowedCompanyIds: string[] | undefined;
  canViewAll: boolean;
  jwtAuthoritative: boolean;
} {
  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();

  if (hasAuthToken() && jwtHome) {
    syncUserHomeFromJwt(user);
    return {
      homeCode: jwtHome,
      allowedCompanyIds: jwtScope.canViewAll
        ? undefined
        : jwtScope.allowedCompanyIds.length > 0
          ? jwtScope.allowedCompanyIds
          : [jwtHome],
      canViewAll: jwtScope.canViewAll,
      jwtAuthoritative: true,
    };
  }

  const scopedUser = user ?? getAuthUser();
  const scope = resolveUserCompanyScope(scopedUser);
  return {
    homeCode: scope.homeCompanyId,
    allowedCompanyIds: scope.canViewAllCompanies ? undefined : scope.allowedCompanyIds,
    canViewAll: scope.canViewAllCompanies === true,
    jwtAuthoritative: false,
  };
}

/** Dev-only — surfaces API URL + tenant mismatch in console. */
export function logTenantDiagnostics(): void {
  if (!appSettings.isDev || typeof window === 'undefined') return;

  const apiUrl = appSettings.apiUrl;
  const active = getActiveCompanyId();
  const jwtHome = readJwtHomeCompanyId();
  const jwtScope = readJwtTenantScope();
  const onLocalhost =
    window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

  if (onLocalhost && apiUrl?.includes('bff.linm-soft.com')) {
    console.warn(
      '[tenant] Local UI but API URL is production BFF. Open http://localhost:8504 (yarn start:std) or fix .env VITE_API_URL.',
      { apiUrl },
    );
  }

  if (jwtHome && active && jwtHome !== active) {
    console.warn('[tenant] X-Company-Id differs from JWT company_id — reconciling', {
      active,
      jwtHome,
      allowed: jwtScope.allowedCompanyIds,
      canViewAll: jwtScope.canViewAll,
    });
  }
}

/**
 * Align `linm_active_company_id` (X-Company-Id) with user/JWT scope.
 * Shell `@linm/nav` owns switch UI; this fixes cross-MFE stale storage (e.g. LINM → UBNA).
 */
export function reconcileActiveCompanyForUser(user: User | null | undefined): void {
  logTenantDiagnostics();

  const { homeCode, allowedCompanyIds, canViewAll, jwtAuthoritative } =
    resolveTenantScope(user);

  if (!homeCode) {
    if (getActiveCompanyId() && jwtAuthoritative) {
      clearActiveCompanyId();
    }
    return;
  }

  const active = getActiveCompanyId();

  // JWT allowlist wins — stale LINM after ERP session must not pass when JWT is UBNA-only.
  if (active && !isTenantSwitchAllowed(active, canViewAll, allowedCompanyIds, homeCode)) {
    setActiveCompanyId(homeCode);
    return;
  }

  if (jwtAuthoritative && !canViewAll && active && active !== homeCode) {
    const allowedSet = new Set(
      (allowedCompanyIds ?? [homeCode]).map(normCompanyCode),
    );
    if (!allowedSet.has(normCompanyCode(active))) {
      setActiveCompanyId(homeCode);
      return;
    }
  }

  const initial = resolveInitialActiveCompanyId(
    homeCode,
    allowedCompanyIds,
    canViewAll,
  );
  const next = initial ?? homeCode;

  if (next !== active) {
    setActiveCompanyId(next);
    return;
  }

  if (!active) {
    setActiveCompanyId(homeCode);
  }
}
